std::optional<Size> iosSymbolSize(const std::string& name, double pointSize, const std::string& weight) {
  const Entry* entry = nullptr;
  for (const auto& e : kSymbols) {
    if (name == e.name) {
      entry = &e;
      break;
    }
  }
  if (entry == nullptr || !(pointSize > 0)) {
    return std::nullopt;
  }
  bool heavy = weight == "semibold" || weight == "bold" || weight == "heavy" || weight == "black";
  size_t base = heavy ? 26 : 0;
  auto at = [&](size_t i) {
    return Size{entry->pixels[base + 2 * i] / 3.0, entry->pixels[base + 2 * i + 1] / 3.0};
  };
  size_t hi = 0;
  while (hi < kPoints.size() && kPoints[hi] < pointSize) {
    hi++;
  }
  if (hi < kPoints.size() && kPoints[hi] == pointSize) {
    return at(hi);
  }
  size_t lo = hi == 0 ? 0 : hi - 1;
  if (hi == kPoints.size()) {
    hi = kPoints.size() - 1;
    lo = hi - 1;
  } else if (hi == 0) {
    hi = 1;
  }
  Size a = at(lo), b = at(hi);
  double t = (pointSize - kPoints[lo]) / (kPoints[hi] - kPoints[lo]);
  auto up = [](double v) { return std::ceil(v * 3 - 1e-6) / 3; };
  return Size{up(a.width + (b.width - a.width) * t), up(a.height + (b.height - a.height) * t)};
}

